if(Application.isPlaying||UnityEngine.SceneManagement.SceneManager.GetActiveScene().isDirty)throw new Exception("Saved edit mode required");
var race=UnityEngine.Object.FindAnyObjectByType<Racer.RaceDirector>();
var data=new {scene=UnityEngine.SceneManagement.SceneManager.GetActiveScene().name,roads=UnityEngine.Object.FindObjectsByType<Racer.RaceRoad>().Select(r=>new{r.name,r.points}),branches=UnityEngine.Object.FindObjectsByType<Racer.WoodlandRoute>().Select(r=>new{r.name,r.points}),gates=race.gates.Select(g=>new{g.name,pos=g.transform.position,g.halfWidth,children=g.GetComponentsInChildren<Transform>().Select(t=>new{t.name,local=t.localPosition,scale=t.localScale,mat=t.GetComponent<Renderer>()?t.GetComponent<Renderer>().sharedMaterial.name:""})}),terrain=GameObject.Find("Memory loop - north is +Z").GetComponentsInChildren<MeshFilter>().Select(m=>new{m.name,path=AssetDatabase.GetAssetPath(m.sharedMesh),vertices=m.sharedMesh.vertexCount,bounds=m.GetComponent<Renderer>().bounds}),objects=UnityEngine.Object.FindObjectsByType<Collider>().Where(c=>c.bounds.center.x>30&&c.bounds.center.x<500&&c.bounds.center.z>-160&&c.bounds.center.z<180).Select(c=>new{c.name,pos=c.transform.position,bounds=c.bounds})};
System.IO.Directory.CreateDirectory("Docs/BackyardForward");System.IO.File.WriteAllText("Docs/BackyardForward/baseline.json",Newtonsoft.Json.JsonConvert.SerializeObject(data,new Newtonsoft.Json.JsonSerializerSettings{ReferenceLoopHandling=Newtonsoft.Json.ReferenceLoopHandling.Ignore,ContractResolver=new Racer.Editor.ForwardJsonResolver()}));
var rows=new List<string>();for(float z=-170;z<=180;z+=10)for(float x=30;x<=500;x+=10){var hit=Physics.RaycastAll(new Vector3(x,250,z),Vector3.down,500,1,QueryTriggerInteraction.Ignore).Where(h=>h.collider.name.StartsWith("Ground_")||h.collider.name=="Decorative Road pavement").OrderBy(h=>h.distance).FirstOrDefault();rows.Add($"{x},{z},{hit.point.y},{hit.collider?.name}");}System.IO.File.WriteAllLines("Docs/BackyardForward/heights.csv",rows);
return "Exported baseline roads, gates, terrain, objects and height samples";
